class TokenBucket {
  constructor(capacity, rate) {
    this.capacity = capacity
    this.rate = rate
    this.tokens = capacity
    this.last = 0
  }

  allow(t) {
    this.tokens = Math.min(this.capacity, this.tokens + (t - this.last) * this.rate)
    this.last = t
    if (this.tokens >= 1) {
      this.tokens -= 1
      return true
    }
    return false
  }
}

function runTokenBucket(capacity, rate, times) {
  const bucket = new TokenBucket(capacity, rate)
  return times.map(t => bucket.allow(t))
}

